import type { ReactNode } from "react"
import { cn } from "@/lib/utils"
import { readableOn, readableOnCss } from "@/lib/readable-on"

type TimelineItem = {
  id: string
  title: ReactNode
  description?: ReactNode
  timestamp?: string
  icon?: ReactNode
  /** A person instead of the dot, for activity feeds: an Avatar, for example. */
  avatar?: ReactNode
  /** Fill of the dot. The glyph inside switches between white and a dark colour so it stays readable (WCAG 1.4.11). */
  color?: string
}

/** Dot fill plus a glyph colour with enough contrast on it. */
function dotStyle(color: string | undefined) {
  const tone = color ? readableOn(color) : "light"
  return {
    className: tone === "dark" ? "text-neutral-dark-content" : "text-white",
    // A fill that is not a literal colour (var(), color-mix) is resolved in CSS.
    style: {
      backgroundColor: color ?? "var(--primary)",
      ...(tone === null && color ? { color: readableOnCss(color) } : null),
    },
  }
}

function Timeline({
  items,
  orientation = "vertical",
  compact = false,
  className,
}: {
  items: TimelineItem[]
  /** "vertical" stacks the entries, "horizontal" lays them out in a row with the time above each dot. */
  orientation?: "vertical" | "horizontal"
  /** Smaller dots and text, for milestones and long lists. */
  compact?: boolean
  className?: string
}) {
  const dot = (item: TimelineItem) =>
    item.avatar ?? (
      <span
        data-slot="timeline-dot"
        className={cn(
          "flex shrink-0 items-center justify-center rounded-full",
          compact ? "size-4 [&_svg]:size-2.5" : "size-6",
          dotStyle(item.color).className
        )}
        style={dotStyle(item.color).style}
      >
        {item.icon ?? <span className={cn("rounded-full bg-current", compact ? "size-1" : "size-1.5")} />}
      </span>
    )

  if (orientation === "horizontal") {
    return (
      <div data-slot="timeline" data-orientation="horizontal" className={cn("flex", className)}>
        {items.map((item, i) => (
          <div key={item.id} className="flex min-w-0 flex-1 flex-col gap-2">
            {item.timestamp && <span className="text-xs text-text-tertiary">{item.timestamp}</span>}
            <div className="flex items-center">
              {dot(item)}
              {i !== items.length - 1 && <span className="mx-2 h-px flex-1 bg-border" />}
            </div>
            <div className="flex flex-col gap-0.5 pr-3">
              <p className={cn("font-semibold text-foreground", compact ? "text-xs" : "text-sm")}>{item.title}</p>
              {item.description && <p className={cn("text-text-secondary", compact ? "text-xs" : "text-[13px]")}>{item.description}</p>}
            </div>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div data-slot="timeline" className={cn("flex flex-col", className)}>
      {items.map((item, i) => (
        <div key={item.id} className="flex gap-3">
          <div className="flex flex-col items-center">
            {dot(item)}
            {i !== items.length - 1 && <span className="my-1 w-px flex-1 bg-border" />}
          </div>
          <div className={cn("flex flex-col gap-0.5", i !== items.length - 1 && (compact ? "pb-4" : "pb-6"))}>
            <div className="flex items-center gap-2">
              <p className={cn("font-semibold text-foreground", compact ? "text-xs" : "text-sm")}>{item.title}</p>
              {item.timestamp && (
                <span className="text-xs text-text-tertiary">{item.timestamp}</span>
              )}
            </div>
            {item.description && (
              <p className={cn("text-text-secondary", compact ? "text-xs" : "text-[13px]")}>{item.description}</p>
            )}
          </div>
        </div>
      ))}
    </div>
  )
}

export { Timeline }
export type { TimelineItem }

/**
 * Picks the glyph colour for text or an icon drawn on an arbitrary fill.
 *
 * `readableOn("#FACA4A")` returns "dark" (white would be 1.6:1, the dark
 * content colour 9.8:1). A fill the function cannot parse (var(), named
 * colours, color-mix()) returns null; the caller then lets CSS decide.
 */

const DARK_CONTENT = "#25272A" // --neutral-dark-content

function channel(value: number) {
  const v = value / 255
  return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4
}

function luminance([r, g, b]: [number, number, number]) {
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b)
}

function parseColor(input: string): [number, number, number] | null {
  const value = input.trim().toLowerCase()
  const hex = /^#([0-9a-f]{3,8})$/.exec(value)
  if (hex) {
    let h = hex[1]
    if (h.length === 3 || h.length === 4) h = [...h].map((c) => c + c).join("")
    if (h.length !== 6 && h.length !== 8) return null
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)]
  }
  const rgb = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/.exec(value)
  if (rgb) return [Number(rgb[1]), Number(rgb[2]), Number(rgb[3])]
  return null
}

/** "light" = white glyph, "dark" = dark glyph, whichever has the higher WCAG contrast; null = unknown fill. */
export function readableOn(fill: string): "light" | "dark" | null {
  const rgb = parseColor(fill)
  if (!rgb) return null
  const y = luminance(rgb)
  const white = 1.05 / (y + 0.05)
  const dark = (y + 0.05) / (luminance(parseColor(DARK_CONTENT)!) + 0.05)
  return white >= dark ? "light" : "dark"
}

/**
 * CSS-only counterpart for fills that are not literal colours (relative colour
 * syntax: white on dark fills, a near-black on light ones, switching at the
 * point where both have the same contrast).
 */
export function readableOnCss(fill: string): string {
  return `oklch(from ${fill} clamp(0.25, (0.6 - l) * 1000, 1) 0 0)`
}

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})
